    col_panels = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]
    out = [row[:] for row in grid]

    def pattern(band, panel):
        y0, y1 = row_bands[band]
        x0, x1 = col_panels[panel]
        return [[grid[r][c] for c in range(x0, x1)] for r in range(y0, y1)]

    def occupied(mat):
        return any(v not in (0, sep) for row in mat for v in row)

    # A neighboring pair is a mirror pair if an example band contains exact
    # left-right reflections. Use that demonstrated relation to complete
    # single-sided instances of the same pair in other bands.
